CREATE TABLE IF NOT EXISTS "migrations" ("id" integer primary key autoincrement not null, "migration" varchar not null, "batch" integer not null);
CREATE TABLE IF NOT EXISTS "personal_access_tokens" ("id" integer primary key autoincrement not null, "tokenable_type" varchar not null, "tokenable_id" integer not null, "name" text not null, "token" varchar not null, "abilities" text, "last_used_at" datetime, "expires_at" datetime, "created_at" datetime, "updated_at" datetime);
CREATE TABLE IF NOT EXISTS "sessions" ("id" varchar not null, "user_id" integer, "ip_address" varchar, "user_agent" text, "payload" text not null, "last_activity" integer not null, primary key ("id"));
CREATE TABLE IF NOT EXISTS "password_reset_tokens" ("email" varchar not null, "token" varchar not null, "created_at" datetime, primary key ("email"));
CREATE TABLE IF NOT EXISTS "units" ("id" integer primary key autoincrement not null, "nama_unit" varchar not null, "created_at" datetime, "updated_at" datetime);
CREATE TABLE IF NOT EXISTS "pegawais" ("id" integer primary key autoincrement not null, "unit_id" integer not null, "nama_pegawai" varchar not null, "jabatan" varchar not null, "created_at" datetime, "updated_at" datetime, foreign key("unit_id") references "units"("id") on delete cascade);
CREATE TABLE IF NOT EXISTS "users" ("id" integer primary key autoincrement not null, "name" varchar not null, "email" varchar not null, "email_verified_at" datetime, "password" varchar not null, "remember_token" varchar, "created_at" datetime, "updated_at" datetime, "role" varchar check ("role" in ('admin', 'pegawai', 'umum')) not null default 'pegawai', "deleted_at" datetime, "nip" varchar, "phone" varchar, "organization" varchar, "address" text, "profile_photo_path" varchar);
CREATE TABLE IF NOT EXISTS "disposisis" ("id" integer primary key autoincrement not null, "surat_id" integer not null, "pengirim_id" integer not null, "penerima_id" integer not null, "isi_disposisi" text not null, "status" varchar check ("status" in ('baru', 'dibaca', 'diproses', 'selesai')) not null default 'baru', "tanggal_disposisi" date, "created_at" datetime, "updated_at" datetime, foreign key("surat_id") references "surats"("id") on delete cascade, foreign key("pengirim_id") references "users"("id") on delete cascade, foreign key("penerima_id") references "users"("id") on delete cascade);
CREATE TABLE IF NOT EXISTS "cache" ("key" varchar not null, "value" text not null, "expiration" integer not null, primary key ("key"));
CREATE TABLE IF NOT EXISTS "cache_locks" ("key" varchar not null, "owner" varchar not null, "expiration" integer not null, primary key ("key"));
CREATE TABLE IF NOT EXISTS "permissions" ("id" integer primary key autoincrement not null, "name" varchar not null, "guard_name" varchar not null, "created_at" datetime, "updated_at" datetime);
CREATE TABLE IF NOT EXISTS "roles" ("id" integer primary key autoincrement not null, "name" varchar not null, "guard_name" varchar not null, "created_at" datetime, "updated_at" datetime);
CREATE TABLE IF NOT EXISTS "model_has_permissions" ("permission_id" integer not null, "model_type" varchar not null, "model_id" integer not null, foreign key("permission_id") references "permissions"("id") on delete cascade, primary key ("permission_id", "model_id", "model_type"));
CREATE TABLE IF NOT EXISTS "model_has_roles" ("role_id" integer not null, "model_type" varchar not null, "model_id" integer not null, foreign key("role_id") references "roles"("id") on delete cascade, primary key ("role_id", "model_id", "model_type"));
CREATE TABLE IF NOT EXISTS "role_has_permissions" ("permission_id" integer not null, "role_id" integer not null, foreign key("permission_id") references "permissions"("id") on delete cascade, foreign key("role_id") references "roles"("id") on delete cascade, primary key ("permission_id", "role_id"));
CREATE TABLE IF NOT EXISTS "jabatan" ("id" integer primary key autoincrement not null, "nama" varchar not null, "created_at" datetime, "updated_at" datetime, "kode" varchar, "deskripsi" text);
CREATE TABLE IF NOT EXISTS "unit_kerja" ("id" integer primary key autoincrement not null, "nama" varchar not null, "created_at" datetime, "updated_at" datetime, "kode" varchar, "deskripsi" text);
CREATE TABLE IF NOT EXISTS "surat_masuk" ("id" integer primary key autoincrement not null, "nomor_surat" varchar not null, "asal_surat" varchar not null, "jenis" varchar not null, "perihal" varchar not null, "tanggal_surat" date not null, "tanggal_diterima" date not null, "status" varchar check ("status" in ('Belum Diproses', 'Diproses', 'Selesai')) not null, "created_at" datetime, "updated_at" datetime);
CREATE TABLE IF NOT EXISTS "surat_keluar" ("id" integer primary key autoincrement not null, "nomor_surat" varchar not null, "tujuan_surat" varchar not null, "jenis" varchar not null, "perihal" varchar not null, "tanggal_surat" date not null, "penandatangan" varchar not null, "status" varchar check ("status" in ('Draft', 'Menunggu Persetujuan', 'Disetujui', 'Terkirim')) not null default 'Draft', "created_at" datetime, "updated_at" datetime);
CREATE TABLE IF NOT EXISTS "disposisi" ("id" integer primary key autoincrement not null, "surat_id" integer not null, "pengirim_id" integer not null, "catatan" text not null, "prioritas" varchar check ("prioritas" in ('Rendah', 'Sedang', 'Tinggi')) not null default 'Sedang', "tanggal_disposisi" date not null, "created_at" datetime, "updated_at" datetime, "deleted_at" datetime, foreign key("surat_id") references "surats"("id") on delete cascade, foreign key("pengirim_id") references "users"("id") on delete cascade);
CREATE TABLE IF NOT EXISTS "disposisi_tujuans" ("id" integer primary key autoincrement not null, "disposisi_id" integer not null, "pegawai_id" integer not null, "status" varchar check ("status" in ('Belum Dibaca', 'Sudah Dibaca', 'Selesai')) not null default 'Belum Dibaca', "dibaca_pada" datetime, "selesai_pada" datetime, "created_at" datetime, "updated_at" datetime, foreign key("disposisi_id") references "disposisi"("id") on delete cascade, foreign key("pegawai_id") references "pegawai"("id") on delete cascade);
CREATE TABLE IF NOT EXISTS "pegawai" ("id" integer primary key autoincrement not null, "nip" varchar not null, "nama" varchar not null, "email" varchar, "no_hp" varchar, "alamat" text, "jabatan_id" integer, "unit_kerja_id" integer, "created_at" datetime, "updated_at" datetime, "user_id" integer, "deleted_at" datetime, foreign key("unit_kerja_id") references unit_kerja("id") on delete set null on update no action, foreign key("jabatan_id") references jabatan("id") on delete set null on update no action, foreign key("user_id") references "users"("id") on delete set null);
CREATE TABLE IF NOT EXISTS "log_aktivitas" ("id" integer primary key autoincrement not null, "user_id" integer, "action" varchar not null, "description" text, "created_at" datetime, "updated_at" datetime, "surat_id" integer, foreign key("user_id") references users("id") on delete set null on update no action, foreign key("surat_id") references "surats"("id") on delete set null);
CREATE TABLE IF NOT EXISTS "surats" ("id" integer primary key autoincrement not null, "user_id" integer, "jenis_surat" varchar not null, "nomor_surat" varchar not null, "tanggal_surat" date not null, "nomor_agenda" varchar, "kode_surat" varchar, "judul_surat" varchar, "perihal" varchar, "asal_surat" varchar, "tujuan_surat" varchar, "metode" varchar, "deskripsi" text, "file_path" varchar, "is_priority" tinyint(1) not null default ('0'), "status" varchar not null default 'draft', "catatan_admin" text, "created_at" datetime, "updated_at" datetime, "lampiran" varchar, "tanggal_kirim" date, "tanggal_keluar" date, "penandatangan" varchar, "jabatan_pimpinan_id" integer, "nama_pimpinan" varchar, "diteruskan_oleh" integer, "diteruskan_pada" datetime, "metode_penerusan" varchar, "catatan_pengantar" text, "deleted_at" datetime, "kategori_pengajuan" varchar, "nomor_kontak" varchar, "asal_instansi" varchar, foreign key("jabatan_pimpinan_id") references jabatan("id") on delete set null on update no action, foreign key("user_id") references users("id") on delete set null on update no action, foreign key("diteruskan_oleh") references "users"("id") on delete set null);
CREATE TABLE IF NOT EXISTS "settings" ("id" integer primary key autoincrement not null, "key" varchar not null, "value" text, "group" varchar not null default 'general', "created_at" datetime, "updated_at" datetime);

CREATE INDEX "personal_access_tokens_tokenable_type_tokenable_id_index" on "personal_access_tokens" ("tokenable_type", "tokenable_id");
CREATE UNIQUE INDEX "personal_access_tokens_token_unique" on "personal_access_tokens" ("token");
CREATE INDEX "personal_access_tokens_expires_at_index" on "personal_access_tokens" ("expires_at");
CREATE INDEX "sessions_user_id_index" on "sessions" ("user_id");
CREATE INDEX "sessions_last_activity_index" on "sessions" ("last_activity");
CREATE UNIQUE INDEX "users_email_unique" on "users" ("email");
CREATE UNIQUE INDEX "permissions_name_guard_name_unique" on "permissions" ("name", "guard_name");
CREATE UNIQUE INDEX "roles_name_guard_name_unique" on "roles" ("name", "guard_name");
CREATE INDEX "model_has_permissions_model_id_model_type_index" on "model_has_permissions" ("model_id", "model_type");
CREATE INDEX "model_has_roles_model_id_model_type_index" on "model_has_roles" ("model_id", "model_type");
CREATE UNIQUE INDEX "surat_keluar_nomor_surat_unique" on "surat_keluar" ("nomor_surat");
CREATE UNIQUE INDEX "pegawai_email_unique" on "pegawai" ("email");
CREATE UNIQUE INDEX "pegawai_nip_unique" on "pegawai" ("nip");
CREATE UNIQUE INDEX "surats_nomor_surat_unique" on "surats" ("nomor_surat");
CREATE UNIQUE INDEX "pegawai_user_id_unique" on "pegawai" ("user_id");
CREATE UNIQUE INDEX "settings_key_unique" on "settings" ("key");
CREATE INDEX "settings_group_index" on "settings" ("group");
CREATE UNIQUE INDEX "users_nip_unique" on "users" ("nip");
